def longestSubstring(N, S):
    # Function to check if a substring repeats within the string
    def check_repeat(sub):
        index = S.find(sub)
        while index != -1:
            next_index = S.find(sub, index + 1)
            if next_index != -1:
                return True, index
            index = S.find(sub, index + 1)
        return False, -1

    max_length = 0
    result = -1

    # Iterate over all possible lengths of substrings
    for length in range(1, N):
        for i in range(N - length + 1):
            sub = S[i:i + length]
            repeats, first_index = check_repeat(sub)
            if repeats:
                # Check if the substring appears before any overlapping occurrence
                if first_index < i + length:
                    if length > max_length:
                        max_length = length
                        result = sub
                    break  # No need to check further as we need to find the first repeating substring

    return result

# Example usage:
# print(longestSubstring(13, "geeksforgeeks"))  # Output: "geeks"
# print(longestSubstring(8, "heyhheyi"))        # Output: "hey"
